import { Header } from "@/registry/bases/base/blocks/header-03/components/header-03"
import { dictionary } from "@/registry/bases/base/blocks/header-03/header-03-dictionary"

export default async function Page({
  params,
}: {
  params?: Promise<{ lang?: string }>
}) {
  const { lang } = (await params) ?? {}
  const locale = lang === "ar" ? "ar" : "en"
  return (
    <div className="flex min-h-svh flex-col">
      <Header dictionary={dictionary[locale]} lang={locale} />
      <main className="flex-1 bg-muted/40" />
    </div>
  )
}

import { LanguagesIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { HeaderMobileNav } from "@/registry/bases/base/blocks/header-03/components/header-03-mobile-nav"
import { HeaderModeSwitcher } from "@/registry/bases/base/blocks/header-03/components/header-03-mode-switcher"

export type HeaderLink = {
  label: string
  href: string
  /** Marks the link for the page being viewed (aria-current). */
  current?: boolean
}

export type HeaderDictionary = {
  brand: { name: string; href: string }
  navLabel: string
  links: HeaderLink[]
  /** The other locale — rendered as a single icon link. */
  language: {
    /** Accessible verb, e.g. "Switch language". */
    label: string
    /** Target language in its own script, e.g. "العربية". */
    name: string
    href: string
    lang: string
  }
  theme: { label: string }
  action: { label: string; href: string }
  menu: { label: string; open: string; close: string; home: string }
}

export function BrandMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      aria-hidden="true"
      className={cn("size-5", className)}
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M4 20 12 4l8 16" />
      <path d="M7.5 13h9" />
    </svg>
  )
}

export function LanguageLink({
  language,
  className,
}: {
  language: HeaderDictionary["language"]
  className?: string
}) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className={className}
      nativeButton={false}
      render={
        <a href={language.href} hrefLang={language.lang} lang={language.lang} />
      }
    >
      <LanguagesIcon />
      <span className="sr-only">
        {language.label} — {language.name}
      </span>
    </Button>
  )
}

export function Header({
  dictionary,
  lang,
  className,
}: {
  dictionary: HeaderDictionary
  lang: "en" | "ar"
  className?: string
}) {
  const dir = lang === "ar" ? "rtl" : "ltr"

  return (
    <header
      dir={dir}
      className={cn(
        "sticky top-0 z-50 w-full border-b bg-background/95 backdrop-blur supports-backdrop-filter:bg-background/80",
        className
      )}
    >
      <div className="mx-auto flex h-14 w-full max-w-7xl items-center gap-2 px-4 md:gap-4 lg:px-8">
        {/* Start: brand + primary links (tablet and up) */}
        <div className="me-4 hidden items-center md:flex">
          <a
            href={dictionary.brand.href}
            className="me-4 flex items-center gap-2 rounded-md text-foreground outline-none focus-visible:ring-3 focus-visible:ring-ring/50 lg:me-6"
          >
            <BrandMark />
            <span className="hidden font-bold lg:inline-block">
              {dictionary.brand.name}
            </span>
          </a>
          <nav
            aria-label={dictionary.navLabel}
            className="flex items-center gap-6 xl:gap-8"
          >
            {dictionary.links.map((link) => (
              <a
                key={link.href + link.label}
                href={link.href}
                aria-current={link.current ? "page" : undefined}
                className={cn(
                  "rounded-sm text-sm text-muted-foreground transition-colors outline-none hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50",
                  link.current && "text-foreground"
                )}
              >
                {link.label}
              </a>
            ))}
          </nav>
        </div>

        {/* Phone: one "Menu" control replaces the brand and links */}
        <HeaderMobileNav dictionary={dictionary} lang={lang} />

        {/* End: utilities */}
        <div className="ms-auto flex items-center gap-2 md:flex-1 md:justify-end">
          <div className="flex items-center gap-0.5">
            <LanguageLink language={dictionary.language} />
            <HeaderModeSwitcher label={dictionary.theme.label} />
            <Separator orientation="vertical" className="mx-1 h-4 self-center!" />
            <Button
              variant="ghost"
              size="sm"
              className="bg-muted px-4"
              nativeButton={false}
              render={<a href={dictionary.action.href} />}
            >
              {dictionary.action.label}
            </Button>
          </div>
        </div>
      </div>
    </header>
  )
}

"use client"

import * as React from "react"
import { XIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetFooter,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet"
import type { HeaderDictionary } from "@/registry/bases/base/blocks/header-03/components/header-03"

export function HeaderMobileNav({
  dictionary,
  lang,
}: {
  dictionary: HeaderDictionary
  lang: "en" | "ar"
}) {
  const [open, setOpen] = React.useState(false)
  const dir = lang === "ar" ? "rtl" : "ltr"

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger
        render={
          <Button
            variant="ghost"
            className="h-8 touch-manipulation gap-2.5 px-0! hover:bg-transparent aria-expanded:bg-transparent md:hidden dark:hover:bg-transparent"
          />
        }
      >
        {/* Two bars that cross into an X while the menu is open */}
        <span className="relative size-4" aria-hidden="true">
          <span
            className={cn(
              "absolute start-0 block h-0.5 w-4 bg-foreground transition-all duration-150",
              open ? "top-[0.4rem] -rotate-45" : "top-1"
            )}
          />
          <span
            className={cn(
              "absolute start-0 block h-0.5 w-4 bg-foreground transition-all duration-150",
              open ? "top-[0.4rem] rotate-45" : "top-2.5"
            )}
          />
        </span>
        <span className="sr-only">{dictionary.menu.open}</span>
        <span className="text-lg leading-none font-medium" aria-hidden="true">
          {dictionary.menu.label}
        </span>
      </SheetTrigger>
      <SheetContent
        dir={dir}
        side={lang === "ar" ? "right" : "left"}
        showCloseButton={false}
        className="w-full gap-0 bg-background/95 backdrop-blur sm:max-w-sm"
      >
        <div className="flex h-14 shrink-0 items-center justify-between border-b px-6">
          <SheetTitle className="font-bold">{dictionary.brand.name}</SheetTitle>
          <SheetClose render={<Button variant="ghost" size="icon-sm" />}>
            <XIcon />
            <span className="sr-only">{dictionary.menu.close}</span>
          </SheetClose>
        </div>
        <nav
          aria-label={dictionary.navLabel}
          className="flex flex-1 flex-col gap-4 overflow-y-auto px-6 py-6"
        >
          <p className="text-sm font-medium text-muted-foreground">
            {dictionary.menu.label}
          </p>
          <ul className="flex flex-col gap-3">
            <li>
              <a
                href={dictionary.brand.href}
                onClick={() => setOpen(false)}
                className="text-2xl font-medium text-foreground/80 transition-colors hover:text-foreground"
              >
                {dictionary.menu.home}
              </a>
            </li>
            {dictionary.links.map((link) => (
              <li key={link.href + link.label}>
                <a
                  href={link.href}
                  aria-current={link.current ? "page" : undefined}
                  onClick={() => setOpen(false)}
                  className={cn(
                    "text-2xl font-medium text-foreground/80 transition-colors hover:text-foreground",
                    link.current && "text-foreground"
                  )}
                >
                  {link.label}
                </a>
              </li>
            ))}
          </ul>
        </nav>
        <SheetFooter className="border-t p-6">
          <Button
            size="lg"
            className="w-full"
            nativeButton={false}
            render={<a href={dictionary.action.href} />}
            onClick={() => setOpen(false)}
          >
            {dictionary.action.label}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  )
}

"use client"

import * as React from "react"
import { useTheme } from "next-themes"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export function HeaderModeSwitcher({
  label,
  className,
}: {
  label: string
  className?: string
}) {
  const { setTheme, resolvedTheme } = useTheme()

  const toggleTheme = React.useCallback(() => {
    setTheme(resolvedTheme === "dark" ? "light" : "dark")
  }, [resolvedTheme, setTheme])

  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className={cn("group/toggle", className)}
      onClick={toggleTheme}
      title={label}
    >
      {/* Half-filled circle: reads as "light / dark" in either theme */}
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        className="size-4.5"
      >
        <path stroke="none" d="M0 0h24v24H0z" fill="none" />
        <path d="M12 12m-9 0a9 9 0 1 0 18 0a9 9 0 1 0 -18 0" />
        <path d="M12 3l0 18" />
        <path d="M12 9l4.65 -4.65" />
        <path d="M12 14.3l7.37 -7.37" />
        <path d="M12 19.6l8.85 -8.85" />
      </svg>
      <span className="sr-only">{label}</span>
    </Button>
  )
}

